using V=std::array<double,3>;using State=std::array<double,6>;using Matrix=std::array<V,3>;
static const std::array<State,3> states{{{7000,-1200,900,1.5,6.75,-2},{5100,4000,-1800,-4,5,1.25},{-3300,6100,2600,-6,-2,1}}};
static const std::array<V,3> impulses{{{.01,.02,-.03},{-.02,.01,.04},{0,.03,.02}}};
static const State anchor{1000,2000,-500,1,-.3,.2},reference{8000,800,400,1.7,6.5,-1};
static const Matrix attitude{{{0,1,0},{-1,0,0},{0,0,1}}}; // inertial -> body
static const QStringList components{"X","Y","Z","VX","VY","VZ"};
static V scale(V a,double s) {for (auto &x:a) x*=s;return a;}
static V cross(const V &a,const V &b) {return {a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]};}
static double dot(const V &a,const V &b) {double s=0;for (int i=0;i<3;++i) s+=a[i]*b[i];return s;}
static V unit(const V &v) {const double n=std::sqrt(dot(v,v));require(n>1e-12,"Independent impulsive frame is degenerate");return scale(v,1/n);}
static QJsonArray json(const State &a) {QJsonArray v;for (auto x:a) v.append(x);return v;}
static QJsonArray json(const V &a) {return {a[0],a[1],a[2]};}
static QJsonArray json(const Matrix &a) {QJsonArray v;for (auto row:a) v.append(json(row));return v;}
// Basis vectors are columns expressed in inertial axes. These are independent
// vector definitions from NASA's guide, not calls to GMAT frame converters.
static Matrix basis(const QString &mode,const State &state,const State &probe) {
   const Matrix identity{{{1,0,0},{0,1,0},{0,0,1}}};
   if (mode=="MJ2000Eq" || mode=="ProbeMJ2000Eq") return identity;
   if (mode=="Body") return attitude; // rows of A are columns of A^T
   if (mode=="NamedEcliptic") {const double e=84381.448*std::acos(-1.)/(180*3600);return {{{1,0,0},{0,std::cos(e),std::sin(e)},{0,-std::sin(e),std::cos(e)}}};}
   V r{},v{};for (int i=0;i<3;++i) {r[i]=mode=="NamedObject" ? reference[i]-anchor[i]:state[i]-(mode.startsWith("Probe") ? probe[i]:0);v[i]=mode=="NamedObject" ? reference[i+3]-anchor[i+3]:state[i+3]-(mode.startsWith("Probe") ? probe[i+3]:0);}
   const V n=unit(cross(r,v)),radial=unit(r),velocity=unit(v);
   return mode.endsWith("VNB") ? Matrix{velocity,n,cross(velocity,n)}:Matrix{radial,cross(n,radial),n};
}
static V delta(const Matrix &b,const V &d) {V result{};for (int i=0;i<3;++i) for (int j=0;j<3;++j) result[i]+=b[j][i]*d[j];return result;}
